//! Parity with the Python collector: scripted commands in, byte-identical lines out.
//!
//! `tests/fixtures/fleet_parity.json` is a frozen golden file: it was recorded from the Python
//! collector, which was retired on 2026-11-13, and its regenerator went with it. Adjust the fixture
//! by hand only when the contract changes on purpose — it is now the only statement of those bytes.
//!
//! Originally generated by `regen_fleet_parity.py` from
//! the Python tool: its expectations are what the reference implementation printed,
//! never what this crate hoped to print.

use std::collections::HashMap;
use std::fs;
use std::path::{Path, PathBuf};
use std::time::Duration;

use chrono::{DateTime, Utc};
use serde_json::{json, Value};
use sec_digest::fleet_state::exec::Runner;
use sec_digest::fleet_state::probe::parse_hosts;
use sec_digest::fleet_state::{as_lines_at, collect, Config, FleetState, RepoState, ServerProbe};
use sec_digest::timeutil::parse_dt;

struct Scripted {
    hub: PathBuf,
    answers: HashMap<(String, String), String>,
}

fn key_of(argv: &[String], cwd: Option<&Path>, hub: &Path) -> (String, String) {
    let hub = hub.to_string_lossy().to_string();
    let home = std::env::var("HOME").unwrap_or_default();
    let canon = |text: &str| text.replace(&hub, "{hub}").replace(&home, "~");
    let args = argv.iter().map(|part| canon(part)).collect::<Vec<_>>().join("\u{1f}");
    let dir = cwd.map(|dir| canon(&dir.to_string_lossy())).unwrap_or_default();
    (args, dir)
}

impl Scripted {
    fn from_fixture(fixture: &Value, hub: &Path) -> Self {
        let mut answers = HashMap::new();
        for response in fixture["responses"].as_array().expect("responses array") {
            let argv: Vec<String> = response["argv"]
                .as_array()
                .expect("argv array")
                .iter()
                .map(|part| part.as_str().expect("argv string").to_string())
                .collect();
            let cwd = response["cwd"].as_str().unwrap_or("").to_string();
            let text = response["text"].as_str().expect("text").to_string();
            answers.insert((argv.join("\u{1f}"), cwd), text);
        }
        Self {
            hub: hub.to_path_buf(),
            answers,
        }
    }
}

impl Runner for Scripted {
    fn run(&self, argv: &[String], cwd: Option<&Path>, _timeout: Duration) -> String {
        match self.answers.get(&key_of(argv, cwd, &self.hub)) {
            Some(text) => text.clone(),
            None => panic!("unscripted command: {argv:?} cwd={cwd:?}"),
        }
    }
}

/// A runner that must never be asked anything, for the paths that stop earlier.
struct Never;

impl Runner for Never {
    fn run(&self, argv: &[String], _cwd: Option<&Path>, _timeout: Duration) -> String {
        panic!("probed when it should not have: {argv:?}");
    }
}

fn fixture() -> Value {
    let text = fs::read_to_string("tests/fixtures/fleet_parity.json").expect("fleet parity fixture");
    serde_json::from_str(&text).expect("fixture parses")
}

fn clock() -> DateTime<Utc> {
    parse_dt("2026-11-12T09:00:00Z").expect("fixture clock")
}

/// A throwaway hub: the checkouts only have to exist, the waiver register is real.
fn temp_hub(fixture: &Value, label: &str) -> PathBuf {
    let root = std::env::temp_dir().join(format!("sec-digest-{label}-{}", std::process::id()));
    let _ = fs::remove_dir_all(&root);
    fs::create_dir_all(root.join("cms-docker-major/security")).expect("hub dirs");
    fs::create_dir_all(root.join("cms-learn")).expect("learn dir");
    let waivers = serde_json::to_string(&fixture["waivers_json"]).expect("waivers json");
    fs::write(root.join("cms-docker-major/security/waivers.json"), waivers).expect("waivers file");
    root
}

fn strings(value: &Value) -> Vec<String> {
    value
        .as_array()
        .expect("string array")
        .iter()
        .map(|item| item.as_str().expect("string").to_string())
        .collect()
}

fn collect_fixture(fixture: &Value, hub: &Path) -> FleetState {
    let hosts = parse_hosts(fixture["hosts_env"].as_str().expect("hosts_env"));
    let runner = Scripted::from_fixture(fixture, hub);
    collect(&Config::new(hub, hosts), &runner, clock())
}

fn repo_subjects(state: &FleetState) -> Value {
    json!(state.repos.iter().map(|repo| repo.subject.clone()).collect::<Vec<_>>())
}

fn server_json(server: &ServerProbe) -> Value {
    json!({
        "host": server.host,
        "kernel": server.kernel,
        "reboot": server.reboot,
        "secupdates": server.secupdates,
        "disk": server.disk,
        "containers": server.containers,
        "unhealthy": server.unhealthy,
        "restarting": server.restarting,
        "uptime": server.uptime,
        "lastscan": server.lastscan,
        "cms_backup_stale": server.backup_stale,
        "cms_offsite_stale": server.offsite_stale,
        "error": server.error,
    })
}

#[test]
fn the_python_collector_and_this_one_print_the_same_bytes() {
    let fixture = fixture();
    let hub = temp_hub(&fixture, "parity");
    let state = collect_fixture(&fixture, &hub);
    let (repos, servers) = as_lines_at(&state, clock());
    let expected = &fixture["expected"];
    assert_eq!(repos, strings(&expected["repo_lines"]));
    assert_eq!(servers, strings(&expected["server_lines"]));
    assert_eq!(state.repos.len(), 2);
    assert_eq!(state.servers.len(), 3);
    assert!(!repos.is_empty() && !servers.is_empty());
}

#[test]
fn the_state_behind_those_lines_agrees_field_by_field() {
    let fixture = fixture();
    let hub = temp_hub(&fixture, "state");
    let state = collect_fixture(&fixture, &hub);
    let expected = &fixture["expected"];
    assert_eq!(json!(state.errors), expected["errors"]);
    assert_eq!(json!(state.uncovered), expected["uncovered"]);
    assert_eq!(repo_subjects(&state), expected["repo_subjects"]);
    let servers: Vec<Value> = state.servers.iter().map(server_json).collect();
    assert_eq!(json!(servers), expected["servers"]);
}

#[test]
fn a_missing_checkout_is_named_and_no_command_runs() {
    let root = std::env::temp_dir().join(format!("sec-digest-missing-{}", std::process::id()));
    let _ = fs::remove_dir_all(&root);
    fs::create_dir_all(&root).expect("empty hub");
    let state = collect(&Config::new(&root, Vec::new()), &Never, clock());
    let (repos, _) = as_lines_at(&state, clock());
    assert_eq!(state.repos.len(), 2);
    assert_eq!(repos[0], "cms-docker: checkout not found");
    assert_eq!(state.errors.len(), 2);
    assert!(repos.iter().all(|line| line.ends_with("checkout not found")));
}

#[test]
fn a_hub_without_a_register_prints_no_waiver_claim() {
    let root = std::env::temp_dir().join(format!("sec-digest-nowaivers-{}", std::process::id()));
    let _ = fs::remove_dir_all(&root);
    fs::create_dir_all(root.join("cms-docker-major")).expect("dirs");
    fs::create_dir_all(root.join("cms-learn")).expect("dirs");
    struct Silent;
    impl Runner for Silent {
        fn run(&self, _argv: &[String], _cwd: Option<&Path>, _timeout: Duration) -> String {
            String::new()
        }
    }
    let state = collect(&Config::new(&root, Vec::new()), &Silent, clock());
    assert!(state.waivers.is_none());
    let (repos, _) = as_lines_at(&state, clock());
    assert!(!repos.iter().any(|line| line.starts_with("waivers:")));
}

#[test]
fn a_dead_ssh_is_unreachable_with_its_reason() {
    let fixture = fixture();
    let hub = temp_hub(&fixture, "dead-ssh");
    let (_, servers) = as_lines_at(&collect_fixture(&fixture, &hub), clock());
    assert!(servers
        .iter()
        .any(|line| line.starts_with("admin: UNREACHABLE — TimeoutExpired")));
    assert!(!servers.iter().any(|line| line.contains("admin: kernel")));
}

#[test]
fn the_scan_rules_survive_a_real_collection() {
    let fixture = fixture();
    let hub = temp_hub(&fixture, "scan");
    let (_, servers) = as_lines_at(&collect_fixture(&fixture, &hub), clock());
    assert!(servers
        .iter()
        .any(|line| line.contains("scan 2026-11-12T03:00:20Z · 13357 findings")));
    assert!(servers.iter().any(|line| line.contains("SCAN STALE")));
}

#[test]
fn repo_json_keeps_the_error_slot_empty_when_the_repo_answered() {
    let repo = RepoState {
        repo: "cms-learn".to_string(),
        ..RepoState::default()
    };
    assert_eq!(json!({"repo": repo.repo, "error": repo.error}), json!({"repo": "cms-learn", "error": null}));
}
